Here’s a simple **single-file app** that lets you add patients, record and edit visit notes, search patients, and export a backup.

Save this as `physio-notes.html`, then open it in a browser. Data is stored in that browser on that device.

**Privacy note:** This is a basic prototype, not a secure medical-record system. Browser storage is not encrypted or access-controlled, so don’t use it for identifiable patient information unless you’ve assessed the security and legal requirements for your practice.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Physio Visit Notes</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: system-ui, sans-serif;
      color: #1f2937;
      background: #f3f6f8;
    }
    header {
      background: #176b67;
      color: white;
      padding: 1rem 1.5rem;
    }
    header h1 { margin: 0; font-size: 1.4rem; }
    main {
      max-width: 1100px;
      margin: 1.5rem auto;
      padding: 0 1rem;
      display: grid;
      grid-template-columns: 300px 1fr;
      gap: 1rem;
    }
    .panel {
      background: white;
      border-radius: 10px;
      padding: 1rem;
      box-shadow: 0 1px 5px #0001;
    }
    h2, h3 { margin-top: 0; }
    label { display: block; font-weight: 600; margin: 0.75rem 0 0.3rem; }
    input, textarea, button {
      font: inherit;
      border-radius: 6px;
    }
    input, textarea {
      width: 100%;
      padding: 0.6rem;
      border: 1px solid #b7c4c8;
    }
    textarea { min-height: 140px; resize: vertical; }
    button {
      border: 0;
      padding: 0.55rem 0.8rem;
      cursor: pointer;
      background: #176b67;
      color: white;
    }
    button:hover { background: #115450; }
    button.secondary { background: #e4eceb; color: #174b48; }
    button.danger { background: #a63636; }
    .row { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-top: 0.75rem; }
    .patient-list { list-style: none; padding: 0; }
    .patient-list button {
      width: 100%;
      text-align: left;
      margin-bottom: 0.4rem;
      background: #edf4f3;
      color: #174b48;
    }
    .patient-list button.selected { background: #176b67; color: white; }
    .visit {
      border-top: 1px solid #dce5e4;
      padding: 1rem 0;
    }
    .visit p { white-space: pre-wrap; overflow-wrap: anywhere; }
    .muted { color: #5f6f73; }
    @media (max-width: 700px) {
      main { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <header><h1>Physio Visit Notes</h1></header>

  <main>
    <aside class="panel">
      <h2>Patients</h2>
      <form id="patient-form">
        <label for="patient-name">New patient name or ID</label>
        <input id="patient-name" required maxlength="100">
        <div class="row"><button type="submit">Add patient</button></div>
      </form>

      <label for="search">Search</label>
      <input id="search" type="search" placeholder="Search patients">
      <ul id="patient-list" class="patient-list"></ul>

      <button id="export" class="secondary" type="button">Export backup</button>
      <p class="muted">The backup is an unencrypted JSON file.</p>
    </aside>

    <section class="panel">
      <div id="empty-state">
        <h2>Welcome</h2>
        <p>Select a patient or add one to start recording visits.</p>
      </div>

      <div id="patient-view" hidden>
        <h2 id="selected-name"></h2>
        <button id="delete-patient" class="danger" type="button">Delete patient</button>

        <h3 style="margin-top: 1.5rem">Visit notes</h3>
        <form id="visit-form">
          <label for="visit-date">Visit date</label>
          <input id="visit-date" type="date" required>

          <label for="visit-notes">Notes</label>
          <textarea id="visit-notes" required
            placeholder="Assessment, treatment, response, and plan..."></textarea>

          <div class="row">
            <button type="submit" id="save-visit">Add visit</button>
            <button type="button" id="cancel-edit" class="secondary" hidden>
              Cancel edit
            </button>
          </div>
        </form>

        <h3 style="margin-top: 1.5rem">Previous visits</h3>
        <div id="visits"></div>
      </div>
    </section>
  </main>

  <script>
    const STORAGE_KEY = "physio-notes-v1";
    const $ = id => document.getElementById(id);
    let patients = [];
    let selectedId = null;
    let editingId = null;

    try {
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
      patients = Array.isArray(saved) ? saved : [];
    } catch {
      alert("Could not read saved data. Do not add new data until the problem is resolved.");
    }

    function save() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(patients));
        return true;
      } catch {
        alert("Could not save to browser storage. Export your data before closing.");
        return false;
      }
    }

    function today() {
      const d = new Date();
      return [
        d.getFullYear(),
        String(d.getMonth() + 1).padStart(2, "0"),
        String(d.getDate()).padStart(2, "0")
      ].join("-");
    }

    function currentPatient() {
      return patients.find(p => p.id === selectedId);
    }

    function resetVisitForm() {
      editingId = null;
      $("visit-date").value = today();
      $("visit-notes").value = "";
      $("save-visit").textContent = "Add visit";
      $("cancel-edit").hidden = true;
    }

    function render() {
      const list = $("patient-list");
      list.replaceChildren();
      const query = $("search").value.trim().toLowerCase();

      patients
        .filter(p => p.name.toLowerCase().includes(query))
        .sort((a, b) => a.name.localeCompare(b.name))
        .forEach(p => {
          const li = document.createElement("li");
          const button = document.createElement("button");
          button.type = "button";
          button.textContent = p.name;
          if (p.id === selectedId) button.className = "selected";
          button.onclick = () => {
            selectedId = p.id;
            resetVisitForm();
            render();
          };
          li.append(button);
          list.append(li);
        });

      const patient = currentPatient();
      $("empty-state").hidden = !!patient;
      $("patient-view").hidden = !patient;
      if (!patient) return;

      $("selected-name").textContent = patient.name;
      const visits = $("visits");
      visits.replaceChildren();

      if (!patient.visits.length) {
        const message = document.createElement("p");
        message.className = "muted";
        message.textContent = "No visits recorded yet.";
        visits.append(message);
      }

      [...patient.visits]
        .sort((a, b) => b.date.localeCompare(a.date))
        .forEach(visit => {
          const card = document.createElement("article");
          card.className = "visit";

          const date = document.createElement("strong");
          date.textContent = visit.date;

          const notes = document.createElement("p");
          notes.textContent = visit.notes;

          const actions = document.createElement("div");
          actions.className = "row";

          const edit = document.createElement("button");
          edit.type = "button";
          edit.className = "secondary";
          edit.textContent = "Edit";
          edit.onclick = () => {
            editingId = visit.id;
            $("visit-date").value = visit.date;
            $("visit-notes").value = visit.notes;
            $("save-visit").textContent = "Save changes";
            $("cancel-edit").hidden = false;
            $("visit-notes").focus();
          };

          const remove = document.createElement("button");
          remove.type = "button";
          remove.className = "danger";
          remove.textContent = "Delete";
          remove.onclick = () => {
            if (!confirm("Delete this visit note?")) return;
            patient.visits = patient.visits.filter(v => v.id !== visit.id);
            if (editingId === visit.id) resetVisitForm();
            save();
            render();
          };

          actions.append(edit, remove);
          card.append(date, notes, actions);
          visits.append(card);
        });
    }

    $("patient-form").onsubmit = event => {
      event.preventDefault();
      const name = $("patient-name").value.trim();
      if (!name) return;
      const patient = { id: crypto.randomUUID(), name, visits: [] };
      patients.push(patient);
      selectedId = patient.id;
      $("patient-name").value = "";
      $("search").value = "";
      resetVisitForm();
      save();
      render();
    };

    $("visit-form").onsubmit = event => {
      event.preventDefault();
      const patient = currentPatient();
      const date = $("visit-date").value;
      const notes = $("visit-notes").value.trim();
      if (!patient || !date || !notes) return;

      if (editingId) {
        const visit = patient.visits.find(v => v.id === editingId);
        if (visit) Object.assign(visit, { date, notes });
      } else {
        patient.visits.push({ id: crypto.randomUUID(), date, notes });
      }
      save();
      resetVisitForm();
      render();
    };

    $("cancel-edit").onclick = resetVisitForm;
    $("search").oninput = render;

    $("delete-patient").onclick = () => {
      const patient = currentPatient();
      if (!patient || !confirm(`Delete ${patient.name} and all their visit notes?`)) return;
      patients = patients.filter p => p.id !== selectedId);
      selectedId = null;
      resetVisitForm();
      save();
      render();
    };

    $("export").onclick = () => {
      const blob = new Blob([JSON.stringify(patients, null, 2)], {
        type: "application/json"
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `physio-notes-backup-${today()}.json`;
      link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    };

    resetVisitForm();
    render();
  </script>
</body>
</html>
```

One correction before running: in the **Delete patient** handler, replace this line:

```js
patients = patients.filter p => p.id !== selectedId);
```

with:

```js
patients = patients.filter(p => p.id !== selectedId);
```

The export is a backup file; this version doesn’t include an import feature. Clearing browser data can erase the saved notes.

